using System;using System.ComponentModel;using System.Diagnostics;using System.Drawing;using System.IO;using System.Reflection;using System.Security.Cryptography;using System.ServiceProcess;using System.Text;using System.Threading;using System.Windows.Forms;using Microsoft.Win32;
namespace MrDaktilo.Startup {
 public interface IUsbPlatform { bool Ready();bool Present();int Install(bool existing);void Pause(); }
 public static class AutoUsb {
 const string PackageHash="1C984914AEC944DE19B64EFF232421439629699F8138E3DDC29301175BC6D938";
 static int started;
 public static int Ensure(IUsbPlatform platform,Action<string> state){if(platform.Ready()){state("USB bileşeni: Hazır");return 0;}bool existing=platform.Present();state(existing?"USB bileşeni: Servis başlatılıyor…":"USB bileşeni: Otomatik kuruluyor…");int exit=platform.Install(existing);if(exit==1223){state("USB bileşeni: Yönetici izni verilmedi");return 2;}if(exit==1460){state("USB bileşeni: Kurulum sürüyor; tamamlanınca yeniden açın");return 3;}if(exit!=0&&exit!=3010){state("USB bileşeni: Kurulum tamamlanamadı ("+exit+")");return 4;}for(int i=0;i<20;i++){if(platform.Ready()){state("USB bileşeni: Hazır");return 0;}platform.Pause();}state(exit==3010?"USB bileşeni: Windows yeniden başlatılmalı":"USB bileşeni: Hazır değil; kurulum günlüğünü kontrol edin");return 5;}
 public static void Begin(Form form,bool sharing){if(!sharing||form==null)return;var preview=form.GetType().GetField("previewMode",BindingFlags.Instance|BindingFlags.NonPublic);if(preview!=null&&(bool)preview.GetValue(form))return;if(Interlocked.Exchange(ref started,1)!=0)return;Post(form,()=>SetLabel(form,"status","USB bileşenleri hazırlanıyor. Ardından bağlantı kodu alınacak."));var thread=new Thread(()=>{Mutex gate=null;bool owned=false;try{gate=new Mutex(false,@"Local\MRDaktilo.AutoUsbHost");try{owned=gate.WaitOne(0);}catch(AbandonedMutexException){owned=true;}if(owned)Ensure(new WindowsUsbPlatform(),text=>Post(form,()=>SetLabel(form,"usbState",text)));else Post(form,()=>SetLabel(form,"usbState","USB bileşeni: Diğer kurulum devam ediyor"));}catch(Exception error){Post(form,()=>SetLabel(form,"usbState","USB bileşeni: "+SafeMessage(error)));}finally{if(owned&&gate!=null)gate.ReleaseMutex();if(gate!=null)gate.Dispose();Post(form,()=>{if(form.IsDisposed)return;var start=form.GetType().GetMethod("Start",BindingFlags.Instance|BindingFlags.NonPublic);if(start!=null)start.Invoke(form,new object[]{true});});}});thread.IsBackground=true;thread.Start();}
 static string SafeMessage(Exception e){var w=e as Win32Exception;return w!=null&&w.NativeErrorCode==1223?"Yönetici izni verilmedi":e.Message;}
 static void SetLabel(Form form,string field,string text){var f=form.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance);var label=f==null?null:f.GetValue(form) as Label;if(label!=null&&!label.IsDisposed)label.Text=text;}
 static void Post(Form form,Action action){try{if(!form.IsDisposed&&form.IsHandleCreated)form.BeginInvoke(action);}catch(InvalidOperationException){}}
 sealed class WindowsUsbPlatform:IUsbPlatform {
 public bool Present(){try{using(var key=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\usbipd-win")){if(key!=null){string dir=key.GetValue("APPLICATIONFOLDER") as string;if(dir!=null&&File.Exists(Path.Combine(dir,"usbipd.exe")))return true;}}string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"usbipd-win","usbipd.exe");return File.Exists(path);}catch{return false;}}
 public bool Ready(){if(!Present())return false;try{using(var service=new ServiceController("usbipd"))return service.Status==ServiceControllerStatus.Running;}catch{return false;}}
 public void Pause(){Thread.Sleep(500);}
 public int Install(bool existing){string dir=Path.Combine(Path.GetTempPath(),"MRDaktilo-USB-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string script=Path.Combine(dir,"prepare-usb.ps1"),result=Path.Combine(dir,"result.txt"),msi=Path.Combine(dir,"usbipd.msi");string body;
 if(existing){body="$ErrorActionPreference='Stop'\ntry { Start-Service -Name 'usbipd'; Set-Content -LiteralPath '"+Q(result)+"' -Value '0'; exit 0 } catch { $_ | Out-File -LiteralPath '"+Q(Path.Combine(dir,"error.log"))+"'; Set-Content -LiteralPath '"+Q(result)+"' -Value '1'; exit 1 }\n";}
 else{using(var input=Assembly.GetEntryAssembly().GetManifestResourceStream("Daktilo.UsbHost")){if(input==null)throw new IOException("Gömülü USB kurucusu bulunamadı.");using(var output=new FileStream(msi,FileMode.CreateNew,FileAccess.Write,FileShare.None))input.CopyTo(output);}using(var stream=File.OpenRead(msi))using(var sha=SHA256.Create()){if(BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","")!=PackageHash)throw new IOException("USB kurucusu bütünlük doğrulaması başarısız.");}
 body=FreshScript(msi,result,dir);}
 File.WriteAllText(script,body,new UTF8Encoding(true));var info=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe"),"-NoProfile -NonInteractive -ExecutionPolicy Bypass -File \""+script+"\""){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden};try{using(var process=Process.Start(info)){if(process==null)return 1;if(!process.WaitForExit(180000))return 1460;int code;return File.Exists(result)&&int.TryParse(File.ReadAllText(result).Trim(),out code)?code:process.ExitCode;}}catch(Win32Exception error){if(error.NativeErrorCode==1223)return 1223;throw;}}
 public static string FreshScript(string msi,string result,string dir){return "$ErrorActionPreference='Stop'\ntry {\n $msi='"+Q(msi)+"'\n if((Get-FileHash -LiteralPath $msi -Algorithm SHA256).Hash -ne '"+PackageHash+"'){throw 'Package integrity failure'}\n $before=@(Get-NetFirewallRule -DisplayName 'usbipd' -ErrorAction SilentlyContinue | ForEach-Object {$_.Name})\n $p=Start-Process -FilePath \"$env:WINDIR\\System32\\msiexec.exe\" -ArgumentList ('/i \"'+$msi+'\" /passive /norestart /L*v \""+Q(Path.Combine(dir,"msi.log"))+"\"') -Wait -PassThru\n $code=$p.ExitCode\n Get-NetFirewallRule -DisplayName 'usbipd' -ErrorAction SilentlyContinue | Where-Object {$before -notcontains $_.Name} | Disable-NetFirewallRule; if($code -eq 0){Start-Service -Name 'usbipd'}\n Set-Content -LiteralPath '"+Q(result)+"' -Value $code\n exit $code\n} catch { $_ | Out-File -LiteralPath '"+Q(Path.Combine(dir,"error.log"))+"'; Set-Content -LiteralPath '"+Q(result)+"' -Value '1'; exit 1 }\n";}
 static string Q(string s){return s.Replace("'","''");}
 }
 sealed class Fake:IUsbPlatform {public int calls,pauses,exit;public bool present,initial,after;public bool Ready(){return calls==0?initial:after;}public bool Present(){return present;}public int Install(bool existing){calls++;if(existing!=present)throw new Exception("Wrong install/start plan");return exit;}public void Pause(){pauses++;}}
 public static void Test(){string state="";Action<string> status=s=>state=s;var ready=new Fake{initial=true};if(Ensure(ready,status)!=0||ready.calls!=0)throw new Exception("Installed case reinstalled");var fresh=new Fake{after=true};if(Ensure(fresh,status)!=0||fresh.calls!=1)throw new Exception("Fresh installation failed");var stopped=new Fake{present=true,after=true};if(Ensure(stopped,status)!=0||stopped.calls!=1)throw new Exception("Service start failed");var denied=new Fake{exit=1223};if(Ensure(denied,status)!=2||!state.Contains("verilmedi"))throw new Exception("UAC cancellation not handled");var failed=new Fake{exit=1603};if(Ensure(failed,status)!=4)throw new Exception("MSI failure not handled");var reboot=new Fake{exit=3010};if(Ensure(reboot,status)!=5||!state.Contains("yeniden"))throw new Exception("Reboot not handled");var pending=new Fake{exit=1460};if(Ensure(pending,status)!=3)throw new Exception("Pending installer not handled");}
 }
}
